func init() {
	AssignmentsTable.Annotation = &entsql.Annotation{}
	AssignmentsTable.Annotation.Checks = map[string]string{
		"platforms_enum": "jsonb_typeof(\"platforms\") = 'array' AND \"platforms\" <@ '[\"dy\",\"xhs\"]'::jsonb",
		"source_enum":    "\"source\" IN ('claim', 'assigned', 'reissued')",
		"status_enum":    "\"status\" IN ('in_progress', 'pending_review', 'rejected', 'pending_settlement', 'settled', 'revoked', 'expired', 'not_payable')",
		"steps_enum":     "jsonb_typeof(\"steps\") = 'array' AND \"steps\" <@ '[\"content\",\"publish\",\"links\",\"data\",\"settle\"]'::jsonb",
	}
	AuditEventsTable.Annotation = &entsql.Annotation{}
	AuditEventsTable.Annotation.Checks = map[string]string{
		"audit_action_enum_v6": "\"action\" IN ('enrollment.apply', 'enrollment.approved', 'enrollment.rejected', 'enrollment.portrait_updated', 'marketing_tag.create', 'marketing_tag.rename', 'marketing_tag.delete', 'user.block', 'user.profile_update', 'user.phone_verify', 'user.identity_verify', 'user.identity_verify_failed', 'enrollment.identity_verify', 'enrollment.identity_verify_failed', 'agreement.consent', 'agreement.publish', 'task.create', 'task.publish_version', 'task.visibility', 'task.claim', 'task.assigned', 'task.revoke', 'task.reissue', 'task.expire', 'marketing.settings', 'submission.submit', 'submission.approved', 'submission.rejected', 'submission.waive', 'settlement.credit', 'withdrawal.request', 'ledger.adjust', 'content.create', 'content.tags_updated', 'feedback.reply', 'operator.create', 'operator.update')",
	}
	FeedbacksTable.Annotation = &entsql.Annotation{}
	FeedbacksTable.Annotation.Checks = map[string]string{
		"status_enum": "\"status\" IN ('open', 'replied', 'closed')",
	}
	FileObjectsTable.Annotation = &entsql.Annotation{}
	FileObjectsTable.Annotation.Checks = map[string]string{
		"media_type_enum": "\"media_type\" IN ('image/jpeg', 'image/png', 'image/gif', 'image/webp', 'video/mp4')",
		"status_enum":     "\"status\" IN ('pending', 'ready')",
		"storage_enum":    "\"storage\" IN ('local', 'tos')",
	}
	JobsTable.Annotation = &entsql.Annotation{}
	JobsTable.Annotation.Checks = map[string]string{
		"kind_enum":   "\"kind\" IN ('transfer', 'transfer_query', 'notification', 'visibility_check')",
		"status_enum": "\"status\" IN ('queued', 'running', 'done', 'retry', 'failed', 'blocked_config')",
	}
	LedgerEntriesTable.Annotation = &entsql.Annotation{}
	LedgerEntriesTable.Annotation.Checks = map[string]string{
		"kind_enum": "\"kind\" IN ('settlement_credit', 'withdrawal_freeze', 'withdrawal_success', 'withdrawal_refund', 'adjustment')",
	}
	MarketingSettingsTable.Annotation = &entsql.Annotation{}
	MarketingSettingsTable.Annotation.Checks = map[string]string{
		"expiry_mode_enum": "\"expiry_mode\" IN ('fixed_duration', 'end_of_day')",
	}
	OperatorsTable.Annotation = &entsql.Annotation{
		Table: "operators",
	}
	OperatorsTable.Annotation.Checks = map[string]string{
		"operator_super_admin_enabled": "NOT super_admin OR NOT disabled",
	}
	SessionsTable.Annotation = &entsql.Annotation{}
	SessionsTable.Annotation.Checks = map[string]string{
		"role_enum": "\"role\" IN ('admin', 'user')",
	}
	SettlementLinesTable.Annotation = &entsql.Annotation{}
	SettlementLinesTable.Annotation.Checks = map[string]string{
		"platform_enum": "\"platform\" IN ('dy', 'xhs')",
	}
	SubmissionsTable.Annotation = &entsql.Annotation{}
	SubmissionsTable.Annotation.Checks = map[string]string{
		"platform_enum":   "\"platform\" IN ('dy', 'xhs')",
		"status_enum":     "\"status\" IN ('pending', 'approved', 'rejected', 'invalid', 'waived')",
		"visibility_enum": "\"visibility\" IN ('unchecked', 'manual_verified', 'visible', 'unavailable', 'unknown')",
	}
	TaskVersionsTable.Annotation = &entsql.Annotation{}
	TaskVersionsTable.Annotation.Checks = map[string]string{
		"platforms_enum": "jsonb_typeof(\"platforms\") = 'array' AND \"platforms\" <@ '[\"dy\",\"xhs\"]'::jsonb",
	}
	UserEnrollmentsTable.ForeignKeys[0].RefTable = UsersTable
	UserEnrollmentsTable.Annotation = &entsql.Annotation{}
	UserEnrollmentsTable.Annotation.Checks = map[string]string{
		"age_group_enum": "\"age_group\" IN ('18_24', '25_30', '31_40', 'over_40', 'unknown')",
		"status_enum":    "\"status\" IN ('none', 'pending', 'approved', 'rejected')",
	}
	UserPlatformProfilesTable.ForeignKeys[0].RefTable = UsersTable
	UserVerificationsTable.ForeignKeys[0].RefTable = UsersTable
	WechatIdentitiesTable.ForeignKeys[0].RefTable = UsersTable
	WithdrawalsTable.Annotation = &entsql.Annotation{}
	WithdrawalsTable.Annotation.Checks = map[string]string{
		"status_enum": "\"status\" IN ('queued', 'submitting', 'unknown', 'waiting_confirmation', 'success', 'failed', 'cancelled', 'blocked_config')",
	}
}
